

select * from customers;
-- 1. What is the total revenue generated by male vs. female customers?
SELECT 
	gender,
    SUM(purchase_amount) AS total_revenue
FROM customers
GROUP BY gender;

-- 2. Which customers used a discount but still spent more than the average purchase amount? 
SELECT 
	TOP 10
	customer_id,
	discount_applied
FROM customers
WHERE discount_applied = 'YES' 
	AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customers);

-- 3. Which are the top 5 products with the highest average review rating?
SELECT TOP 5
	item_purchased,
	ROUND(AVG(CAST(review_rating AS FLOAT)), 2) AS avg_rating
FROM customers
GROUP BY item_purchased
ORDER BY avg_rating DESC;

-- 4. Compare the average Purchase Amounts between Standard and Express Shipping. 
SELECT 
	shipping_type,
	ROUND(AVG(CAST(purchase_amount AS FLOAT)), 2) AS Avg_purchase_amt
FROM customers
WHERE shipping_type IN ('Express', 'Standard')
GROUP BY shipping_type;

-- 5. Do subscribed customers spend more? Compare average spend and total revenue 
-- between subscribers and non-subscribers.
SELECT 
	subscription_status,
	COUNT(customer_id) AS total_subscribers,
	ROUND(AVG(CAST(purchase_amount AS FLOAT)), 2) AS Avg_purchase_amt,
	SUM(purchase_amount) AS Avg_purchase_amt
FROM customers
GROUP BY subscription_status;

-- 6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT
    TOP 5
    item_purchased,
    ROUND(100.0 * SUM(CAST(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END AS FLOAT)) / COUNT(*), 2) AS discount_rate
FROM customers
GROUP BY item_purchased
ORDER BY discount_rate DESC;

-- 7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
	WITH customer_type AS (SELECT
		customer_id,
		previous_purchases,
		CASE
			WHEN previous_purchases = 1 THEN 'NEW'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'RETURNING'
			ELSE 'LOYAL'
		END AS customer_segment
	FROM customers)

	SELECT
		customer_segment,
		COUNT(customer_segment) as total_customers
	FROM customer_type
	GROUP BY customer_segment
	ORDER BY customer_segment;

-- 8. What are the top 3 most purchased products within each category? 
WITH CTE1 AS (SELECT 
	category,
	count(category) AS total_purchases
FROM customers
GROUP BY category)

SELECT 
	TOP 3 * 
FROM CTE1 
ORDER BY total_purchases DESC;

-- 9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT
	 subscription_status, COUNT(customer_id) as Total_customer
FROM customers
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- 10. What is the revenue contribution of each age group? 
SELECT 
	age_group,
	COUNT(purchase_amount) AS revenue 
FROM customers
GROUP BY age_group
ORDER BY revenue
